// TH16 v1.00a Stage 5 midboss wave. Entry st05.ecl.txt MainSub06:1276-1292;
// dependencies GirlD01:652-674 and GirlD01_at:676-736.
// MainSub06 runs on the stage main script; enmCreate x/y are inputs relative to
// that caller (source x=0 is the field axis), so the girls take the raw offsets.

const TIME_LIMIT: int = 1424;      // 120 opening buffer + 1300 source window
const OPENING_BUFFER: int = 120;
const TH16_RICE: int = 480;        // source etSprite type 8, color 6

// GirlD01_at per-bullet EX chain: ANIM a=1 (birth art omitted; its
// position -= 4*speed = 5.2px is folded into sh_dist below), then
// WAIT 200/200/100/30 and ACCEL a=230 r=0.01 along the bullet's own angle
// (s=-999999 keeps the spawn angle).
xformdef GIRL_SHOT(delay: int) {
    wait(delay);
    set_accel(0.01fx);
    wait(230);
    set_accel(0fx);
}

// GirlD01_at. Difficulty values resolved from the source masks:
// etCount 1/1/1/2, WAIT 200/200/100/30, wait 3/1/1/1, $C 130/400/600/400.
async sub girl_shot() {
    var n: int = 1;
    var delay: int = 200;
    var cadence: int = 3;
    var volleys: int = 130;
    var rank: int = global(GVAR_RANK);
    if rank == 1 { cadence = 1; volleys = 400; }
    if rank == 2 { cadence = 1; volleys = 600; delay = 100; }
    if rank >= 3 { cadence = 1; volleys = 400; delay = 30; n = 2; }

    sh_reset(0);
    sh_sprite(0, TH16_RICE, 6);      // etSprite(0, 8, 6)
    sh_ring(0, 1);                   // etAim(0, 3): fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, n, 1);               // etCount(0, N, 1)
    sh_speed(0, 1.3fx, 0fx);         // etSpeed(0, 1.3, 1.0) with one layer
    sh_dist(0, 26.8fx);              // etDist 32 minus ANIM 4*1.3
    sh_xform(0, GIRL_SHOT(delay));

    var base: int = rand(65536) - 32768;   // %B = %RANDRAD, -pi..pi
    var left: int = volleys;
    loop {
        sh_angle(0, base as angle, 0deg);  // etAngle(0, %B, 0.0)
        base = base + 40503;               // %B += 3.883222 rad
        if base > 32767 { base = base - 65536; }
        sh_fire(0);                        // etOn(0)
        wait(cadence);
        left = left - 1;
        if left <= 0 { return; }
    }
}

// GirlD01: hitboxes and movement; drops/animation omitted.
async sub girl() {
    set_invuln(65535);
    set_hurtbox(16fx);                     // setHurtbox(32, 32)
    set_hitbox(12fx);                      // setHitbox(24, 24)
    move_vel(0, 90deg, 2.5fx, EASE_LINEAR);          // moveVel(pi/2, 2.5)
    move_speed(70, 0.3fx, EASE_QUAD_IN);             // moveVelTime(70, 1, pi/2, 0.3)
    spawn girl_shot();                                // @GirlD01_at() async
    wait(400);
    move_speed(120, 3.0fx, EASE_QUAD_IN);            // moveSpeedTime(120, 1, 3.0)
    loop { wait(1000); }                              // GirlD01_408/GirlD01_428
}

// MainSub06 spawn schedule; source coords, y=-32 above the field top.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -32fx, 2000, 0, 1000, 0, girl);
    wait(200);
    _ = spawn_enemy(0fx, -32fx, 2000, 0, 1000, 0, girl);
    wait(200);
    _ = spawn_enemy(40fx, -32fx, 1500, 0, 1000, 0, girl);
    _ = spawn_enemy(-40fx, -32fx, 1500, 0, 1000, 0, girl);
    wait(200);
    _ = spawn_enemy(90fx, -32fx, 1400, 0, 1000, 0, girl);
    _ = spawn_enemy(-90fx, -32fx, 1400, 0, 1000, 0, girl);
    wait(200);
    _ = spawn_enemy(170fx, -32fx, 1300, 0, 1000, 0, girl);
    _ = spawn_enemy(-170fx, -32fx, 1300, 0, 1000, 0, girl);
    wait(200);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
